# -*- coding: utf-8 -*-
"""
Desktop pet 8-theme asset manager.
"""
import os, sys, base64
from PyQt6.QtGui import QPixmap

_PIXMAP_CACHE = {}

PET_THEME_B64 = {
    "morning": "",
    "noon": "",
    "afternoon": "",
    "evening": "",
    "night": "",
    "rain": "",
    "cold": "",
    "hot": "",
}

def get_pet_pixmap(theme: str = "afternoon") -> QPixmap:
    theme_key = theme.lower()
    if theme_key in _PIXMAP_CACHE:
        return _PIXMAP_CACHE[theme_key]

    search_paths = []
    if hasattr(sys, '_MEIPASS'):
        search_paths.append(os.path.join(sys._MEIPASS, 'app', 'resources', 'pets', f'pet_{theme_key}.png'))
        search_paths.append(os.path.join(sys._MEIPASS, 'resources', 'pets', f'pet_{theme_key}.png'))

    base_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    search_paths.append(os.path.join(base_dir, 'resources', 'pets', f'pet_{theme_key}.png'))
    search_paths.append(os.path.join(os.getcwd(), 'app', 'resources', 'pets', f'pet_{theme_key}.png'))

    for sp in search_paths:
        if os.path.exists(sp):
            px = QPixmap(sp)
            if not px.isNull():
                _PIXMAP_CACHE[theme_key] = px
                return px

    b64_str = PET_THEME_B64.get(theme_key) or PET_THEME_B64.get('afternoon')
    if b64_str:
        raw_bytes = base64.b64decode(b64_str)
        px = QPixmap()
        px.loadFromData(raw_bytes, 'PNG')
        if not px.isNull():
            _PIXMAP_CACHE[theme_key] = px
            return px

    return QPixmap()

def get_pet_board_pixmap() -> QPixmap:
    return get_pet_pixmap("afternoon")